// Generated by Claude - Opus 5.5
// Molina's pond: the animated backdrop, drawn from scratch as SVG + CSS.
// Every moving part also has a resting place, so it still looks finished
// when the app turns animation off (Reduce Motion).
import { loopProgress, type Mover, LOOPS, SPOTS, visitPhase, VISITORS, type VisitorKind } from './layout'
import { fish, JELLY_SVG, MANTA_SVG, molina, ORCA_SVG, PINK_JELLY_SVG, PUFFER_SVG, SHRIMP_SVG, STARFISH_SVG, TETRA_SVG, OCTOPUS_SVG, EEL_SVG, SQUID_SVG, SARDINE_SVG, WHALE_SVG, STRIPEY_SVG, SEAHORSE_SVG, SNAIL_SVG, turtle } from './molina'

// Same "random" numbers every time, so a redraw doesn't reshuffle the pond.
const rnd = (i: number, salt: number) => {
  const v = Math.sin(i * 12.9898 + salt * 78.233) * 43758.5453
  return v - Math.floor(v)
}
const W = 1600
const H = 900
const range = (n: number) => Array.from({ length: n }, (_, i) => i)
const f = (n: number) => n.toFixed(1)

// --- Colors for light and dark mode, switched by the app's mode.
const COLORS = `
.top{stop-color:#d9f4ef}.bot{stop-color:#79c2bc}.ray{fill:#ffffff;opacity:.30}
.shine{fill:#ffffff;opacity:.35}.sand{fill:url(#sand)}.sand2{fill:#dcc59c}.rock{fill:#b5c3bd}.peb{fill:#cdb48d}
.kelpA{fill:url(#kelpA)}.kelpB{fill:url(#kelpB)}.ka0{stop-color:#2f7a64}.ka1{stop-color:#7cc4a4}.kb0{stop-color:#245f52}.kb1{stop-color:#5fae92}
.sun0{stop-color:#ffffff;stop-opacity:.45}.sun1{stop-color:#ffffff;stop-opacity:0}.far{fill:#5aa39c;opacity:.35}
.fog0{stop-color:#79c2bc;stop-opacity:0}.fog1{stop-color:#79c2bc;stop-opacity:.55}.vig0{stop-color:#0b2a33;stop-opacity:0}.vig1{stop-color:#0b2a33;stop-opacity:.14}
.sd0{stop-color:#f1e2c4}.sd1{stop-color:#dcc59c}.caus{fill:#ffffff;opacity:.35}.grass{fill:#5aa877}.moss{fill:#6aa874}.lily{fill:#5f9e62;opacity:.9}
.stem{stroke:#4f8f5c}.bub{fill:none;stroke:#ffffff;stroke-width:2;opacity:.8}.puff{fill:none;stroke:#ffffff;stroke-width:.3}
.mote{fill:#ffffff;opacity:.5}.badge{fill:#f3faf8;fill-opacity:.85;stroke:#D97757;stroke-opacity:.5}
.pct{fill:#b4553a}.lbl{fill:#3a4e55}.anemA{fill:#E98FA8}.anemB{fill:#F2A65A}
@media (prefers-color-scheme: dark){
.top{stop-color:#123a4a}.bot{stop-color:#05141c}.ray{fill:#8fd8e3;opacity:.10}
.shine{fill:#9fe3ef;opacity:.12}.sand2{fill:#1d2725}.rock{fill:#1c2a2f}.peb{fill:#2c3634}
.ka0{stop-color:#0f3a35}.ka1{stop-color:#2e7a6c}.kb0{stop-color:#0b2f2b}.kb1{stop-color:#22645a}
.sun0{stop-color:#9fe3ef;stop-opacity:.16}.far{fill:#0a2a35;opacity:.6}.fog0{stop-color:#05141c;stop-opacity:0}.fog1{stop-color:#05141c;stop-opacity:.6}
.vig1{stop-color:#000000;stop-opacity:.35}.sd0{stop-color:#2c3836}.sd1{stop-color:#1a2321}.caus{fill:#9fe3ef;opacity:.12}.grass{fill:#1d5a4c}.moss{fill:#1c4c40}.lily{fill:#123d33}
.stem{stroke:#0f3a2e}.bub{stroke:#9fe3ef;opacity:.6}.puff{stroke:#9fe3ef}
.mote{fill:#8ff0e0;opacity:.7}.badge{fill:#0b1b22;fill-opacity:.8}.pct{fill:#E8A387}.lbl{fill:#C2D1CF}.anemA{fill:#8B4A62}.anemB{fill:#8A5A2E}}
`

// --- Motion. All slow; the blinking parts are tiny, so nothing flashes.
const MOTION = `
.wave{animation:drift 14s linear infinite}
.ray{animation:breathe 9s ease-in-out infinite alternate}
.kelp,.grass,.stem{transform-box:fill-box;transform-origin:50% 100%;animation:sway 7s ease-in-out infinite alternate}
.grass{animation-duration:4s}
.stem{transform-origin:50% 0%;animation-duration:9s}
.lily{animation:float 24s ease-in-out infinite alternate}
.rise{animation:rise linear infinite}
.paddle{animation:paddle 3s ease-in-out infinite alternate}
.jelly{animation:jelly 9s ease-in-out infinite alternate}
.wob{animation:wobble 3s ease-in-out infinite alternate}
.mote{animation:twinkle 6s ease-in-out infinite alternate}
.molina{animation:bob 4s ease-in-out infinite alternate}
.molina.asleep{animation-duration:7s}
.hop{animation:hop 17s ease-in-out infinite}
.gill{animation:fan 2.4s steps(1) infinite}
.gr{animation-delay:-1.2s}
.tail{animation:fan-x 1.8s steps(1) infinite}
.tail.slow{animation-duration:5s}
.blink{opacity:0;animation:blink 5s steps(1) infinite}
.look{opacity:0;animation:look 13s steps(1) infinite}
.yawn{opacity:0;animation:yawn 9s steps(1) infinite}
.spark{opacity:0;animation:spark 17s steps(1) infinite}
.puff{opacity:0;animation:puff 6s ease-out infinite}
.zed{opacity:0;animation:zed 4.8s ease-out infinite}
.cross,.crossy{animation-timing-function:linear;animation-fill-mode:both}
.cross{animation-name:cross}.crossy{animation-name:crossy}
.swimfin{animation:paddle 2s ease-in-out infinite alternate}
.glide{transform-box:fill-box;transform-origin:50% 50%;animation:glide 3s ease-in-out infinite alternate}
.bobble{animation:jelly 2.5s ease-in-out infinite alternate}
.paddle-fin{animation:fan 1.2s steps(1) infinite}
@keyframes cross{from{transform:translateX(var(--a))}to{transform:translateX(var(--b))}}
@keyframes crossy{from{transform:translateY(var(--a))}to{transform:translateY(var(--b))}}
@keyframes glide{from{transform:scaleY(1)}to{transform:scaleY(.8)}}
.spin,.inflate{transform-box:fill-box;transform-origin:50% 50%}
.spin{animation:spin 40s linear infinite}
.inflate{animation:inflate 7s ease-in-out infinite}
.hop2{animation:hop2 2.6s ease-in-out infinite}
.anem{transform-box:fill-box;transform-origin:50% 100%;animation:sway 3.5s ease-in-out infinite alternate}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes inflate{0%,70%,100%{transform:scale(1)}80%,90%{transform:scale(1.3)}}
@keyframes hop2{0%,60%,100%{transform:translateY(0)}70%{transform:translateY(-14px)}80%{transform:translateY(0)}}
.caus{animation:caus 9s ease-in-out infinite alternate}
@keyframes caus{from{transform:translateX(-30px);opacity:.15}}
.walk{animation:walk 40s ease-in-out infinite alternate}
.face{transform-box:fill-box;transform-origin:50% 50%;animation:face 80s steps(1) infinite}
.roam{animation:roam 60s ease-in-out infinite}
.squish{transform-box:fill-box;transform-origin:50% 0%;animation:squish 2.4s ease-in-out infinite}
.peek{animation:peek 14s ease-in-out infinite}
.orbit{animation:orbit 10s linear infinite}
@keyframes walk{from{transform:translateX(-5vw)}to{transform:translateX(9vw)}}
@keyframes face{0%{transform:scaleX(1)}50%{transform:scaleX(-1)}}
@keyframes roam{0%,100%{transform:translate(0,0)}25%{transform:translate(7vw,-7vh)}50%{transform:translate(13vw,3vh)}75%{transform:translate(5vw,9vh)}}
@keyframes squish{50%{transform:scale(1.08,.88)}}
@keyframes peek{0%,55%,100%{transform:translateY(60px)}65%,90%{transform:translateY(0)}}
@keyframes orbit{from{transform:rotate(0deg) translateX(46px) rotate(0deg)}to{transform:rotate(360deg) translateX(46px) rotate(-360deg)}}
@keyframes drift{to{transform:translateX(200px)}}
@keyframes breathe{from{opacity:.04}}
@keyframes sway{from{transform:rotate(-3deg)}to{transform:rotate(3deg)}}
@keyframes float{to{transform:translateX(40px)}}
@keyframes rise{from{transform:translateY(var(--a))}to{transform:translateY(var(--b))}}
@keyframes paddle{to{transform:translateY(-10px)}}
@keyframes jelly{to{transform:translateY(-60px)}}
@keyframes wobble{to{transform:translateX(8px)}}
@keyframes twinkle{from{opacity:.1}}
@keyframes bob{to{transform:translateY(-3px)}}
@keyframes hop{0%,86%,100%{transform:translateY(0)}89%{transform:translateY(-4px)}92%{transform:translateY(0)}95%{transform:translateY(-2px)}}
@keyframes fan{0%{transform:translateY(0)}25%{transform:translateY(-1px)}50%{transform:translateY(0)}75%{transform:translateY(1px)}}
@keyframes fan-x{0%{transform:translateX(0)}25%{transform:translateX(1px)}50%{transform:translateX(0)}75%{transform:translateX(-1px)}}
@keyframes blink{0%{opacity:0}96%{opacity:1}100%{opacity:0}}
@keyframes look{0%{opacity:0}40%{opacity:1}55%{opacity:0}}
@keyframes yawn{0%{opacity:0}70%{opacity:1}85%{opacity:0}}
@keyframes spark{0%{opacity:0}87%{opacity:1}97%{opacity:0}}
@keyframes puff{0%{opacity:0;transform:translateY(0)}10%{opacity:.9}100%{opacity:0;transform:translateY(-24px)}}
@keyframes zed{0%{opacity:0;transform:translateY(0)}20%{opacity:1}100%{opacity:0;transform:translateY(-8px)}}
`

// A wavy band repeated every 200px, so sliding it 200px loops seamlessly.
const waves = (y: number, amp: number) => {
  let d = `M-200 0V${y}`
  for (let x = -200; x < W + 200; x += 200) d += `q50 ${amp} 100 0t100 0`
  return `${d}V0z`
}

// Bubbles rise from below the floor to above the surface. A negative delay puts
// each one at its resting spot y0, so a redraw never bunches them up.
const travelUp = (y0: number, seconds: number, inner: string) =>
  `<g class="rise" style="--a:${f(H + 40 - y0)}px;--b:${f(-60 - y0)}px;animation-duration:${f(seconds)}s;animation-delay:${f(-((H + 40 - y0) / (H + 100)) * seconds)}s">${inner}</g>`

// --- Plants
const kelp = (x: number, h: number, lean: number, cls: string, i: number) =>
  `<path class="kelp ${cls}" style="animation-delay:${f(-rnd(i, 1) * 7)}s" d="M${x} ${H}C${x - 18} ${H - h * 0.5} ${x + lean - 14} ${H - h * 0.8} ${x + lean} ${H - h}C${x + lean + 16} ${H - h * 0.75} ${x + 22} ${H - h * 0.45} ${x + 14} ${H}Z"/>`

// A tuft of three thin grass blades on the sand.
const tuft = (x: number, y: number, h: number, i: number) => `<g class="grass" style="animation-delay:${f(-rnd(i, 15) * 4)}s">${[-9, 0, 9].map((dx, k) =>
  `<path d="M${x + dx - 3} ${y}Q${x + dx * 2} ${y - h * 0.6} ${x + dx * 1.6 + 2} ${y - h * (0.7 + k * 0.15)}Q${x + dx + 3} ${y - h * 0.4} ${x + dx + 3} ${y}Z"/>`).join('')}</g>` // the whole tuft sways together: one animation, not three

// A sea anemone: a soft mound with tentacles that wave.
const anemone = (x: number, cls: string, i: number) =>
  `<g class="${cls}"><ellipse cx="${x}" cy="842" rx="26" ry="12"/><g class="anem" style="animation-delay:${f(-rnd(i, 23) * 3.5)}s">${range(7).map(k => {
    const tx = x - 21 + k * 7
    return `<path d="M${tx - 3} 838Q${tx - 6 + (k - 3) * 3} 805 ${tx + (k - 3) * 5} ${790 + rnd(k, i) * 15}Q${tx + 4} 812 ${tx + 3} 838Z"/>`
  }).join("")}</g></g>` // all tentacles wave together

// Lily pads at the surface, seen from below, with stems hanging into the water.
const lily = (x: number, r: number, i: number) =>
  `<g class="lily" style="animation-delay:${f(-rnd(i, 16) * 24)}s"><path class="stem" fill="none" stroke-width="3" d="M${x} 34q${8 - i * 4} 120 ${-6 + i * 5} ${180 + r}"/><path d="M${x} 30m${-r} 0a${r} ${r * 0.32} 0 1 0 ${r * 2} 0a${r} ${r * 0.32} 0 0 0 ${-r * 0.9} ${-r * 0.3}l${-r * 0.1} ${r * 0.3}l${-r * 0.2} ${-r * 0.31}a${r} ${r * 0.32} 0 0 0 ${-r * 0.8} ${r * 0.31}z"/></g>`

// --- Animals
const bubble = (i: number) => {
  const y = 60 + rnd(i, 3) * (H - 120)
  return travelUp(y, 14 + rnd(i, 5) * 10,
    `<circle class="bub wob" style="animation-delay:${f(-rnd(i, 6) * 3)}s" cx="${f(40 + rnd(i, 2) * (W - 80))}" cy="${f(y)}" r="${f(3 + rnd(i, 4) * 7)}"/>`)
}
// Plankton twinkles in three groups (three animations, however many specks).
const motes = (n: number) => range(3).map(g =>
  `<g class="mote" style="animation-delay:${-g * 2}s">${range(n).filter(i => i % 3 === g).map(i => `<circle cx="${f(rnd(i, 8) * W)}" cy="${f(80 + rnd(i, 9) * 700)}" r="${f(1.5 + rnd(i, 10) * 2)}"/>`).join('')}</g>`).join('')

// ===== Creatures you can click =====
// They live in window coordinates (percent of the backdrop, sizes in screen
// pixels), so a click's position can be matched to them. See layout.ts.

/** What the pond shows right now. Times are milliseconds since 1970. */
export type View = {
  stage: number // 0 awake .. 3 asleep, from the context window
  percent: number
  now: number
}

// Pin something's center to a fraction of the backdrop.
const pin = (x: number, y: number, inner: string) =>
  `<svg x="${f(x * 100)}%" y="${f(y * 100)}%" width="1" height="1" overflow="visible">${inner}</svg>`

// A creature crossing the backdrop: progress p (0-1) now, looping or once.
const cross = (m: Mover, p: number, loop: boolean, inner: string) => {
  const unit = m.axis === 'x' ? 'vw' : 'vh'
  const where = m.axis === 'x' ? `x="0" y="${f(m.at * 100)}%"` : `x="${f(m.at * 100)}%" y="0"`
  return `<svg ${where} width="1" height="1" overflow="visible"><g class="${m.axis === 'x' ? 'cross' : 'crossy'}" style="--a:${f(m.from * 100)}${unit};--b:${f(m.to * 100)}${unit};animation-duration:${m.seconds}s;animation-delay:${f(-p * m.seconds)}s;animation-iteration-count:${loop ? 'infinite' : 1}">${inner}</g></svg>`
}

// Pixel art scaled by k, centered on (0, 0); `flip` mirrors it to face the other way.
const art = (svg: string, w: number, h: number, k: number, flip = false) =>
  `<g shape-rendering="crispEdges" transform="translate(${f(flip ? (w * k) / 2 : (-w * k) / 2)} ${f((-h * k) / 2)}) scale(${flip ? -k : k} ${k})">${svg}</g>`

const school = (count: number, blue: boolean, right: boolean) => range(count).map(i =>
  `<g class="paddle" style="animation-delay:${f(-i * 0.9)}s"><g transform="translate(${(i - (count - 1) / 2) * 70} ${(i % 2) * 34 - 17})">${art(fish(blue), 10, 5, 6, right)}</g></g>`).join('')

const VISITOR_ART: Record<VisitorKind, string> = {
  orca: art(ORCA_SVG, 30, 12, 7),
  turtle: `<g class="swimfin">${art(turtle(), 22, 9, 8)}</g>`,
  manta: `<g class="glide">${art(MANTA_SVG, 22, 10, 6)}</g>`,
  seahorse: `<g class="bobble">${art(SEAHORSE_SVG, 9, 14, 6)}</g>`,
  whale: `<g opacity="0.28">${art(WHALE_SVG, 28, 7, 14)}</g>`,
  squid: `<g class="squish">${art(SQUID_SVG, 14, 5, 6)}</g>`,
  sardines: range(14).map(i => `<g class="paddle" style="animation-delay:${f(-i * 0.3)}s"><g transform="translate(${(i % 5) * 34 + (i % 2) * 14 - 80} ${Math.floor(i / 5) * 26 - 26})">${art(SARDINE_SVG, 4, 3, 5)}</g></g>`).join(""),
  burst: range(12).map(i => `<circle class="bub wob" style="animation-delay:${f(-rnd(i, 40) * 3)}s" cx="${f(rnd(i, 41) * 70 - 35)}" cy="${f(i * 22 - 120)}" r="${f(3 + rnd(i, 42) * 6)}"/>`).join(""),
}

// Each visitor crosses once per cycle and waits off screen for the rest of it,
// on the timetable in layout.ts, so arrivals need no redraw.
const visitorCss = (kind: VisitorKind) => {
  const v = VISITORS[kind], unit = v.axis === "x" ? "X" : "Y", u = v.axis === "x" ? "vw" : "vh"
  const end = f((v.seconds / v.every) * 100)
  return `@keyframes v-${kind}{0%{transform:translate${unit}(${f(v.from * 100)}${u})}${end}%,100%{transform:translate${unit}(${f(v.to * 100)}${u})}}`
}
const visitor = (kind: VisitorKind, now: number) => {
  const v = VISITORS[kind]
  const where = v.axis === "x" ? `x="0" y="${f(v.at * 100)}%"` : `x="${f(v.at * 100)}%" y="0"`
  return `<svg ${where} width="1" height="1" overflow="visible"><g style="animation:v-${kind} ${v.every}s linear ${f(-visitPhase(kind, now))}s infinite both">${VISITOR_ART[kind]}</g></svg>`
}

const creatures = (v: View) => {
  return `
<style>${(Object.keys(VISITORS) as VisitorKind[]).map(visitorCss).join("")}</style>
<!-- the jellyfish drift around on slow loops; the octopus wanders and squishes as it swims -->
${pin(SPOTS.jelly.x, SPOTS.jelly.y, `<g class="roam"><g class="jelly" opacity="0.88">${art(JELLY_SVG, 7, 8, 9)}</g></g>`)}
${pin(0.66, 0.33, `<g class="roam" style="animation-duration:75s;animation-direction:reverse"><g class="jelly" style="animation-delay:-4s" opacity="0.8">${art(PINK_JELLY_SVG, 7, 8, 6)}</g></g>`)}
${pin(0.3, 0.6, `<g class="roam" style="animation-duration:90s;animation-delay:-30s"><g class="squish">${art(OCTOPUS_SVG, 11, 10, 6)}</g></g>`)}
<!-- an eel peeks out of its rock now and then -->
${pin(0.63, 0.9, `<clipPath id="hole"><rect x="-40" y="-140" width="80" height="146"/></clipPath><g clip-path="url(#hole)"><g class="peek">${art(EEL_SVG, 7, 13, 5)}</g></g><path class="rock" d="M-50 40C-45 5 -20 -2 0 -2S45 5 50 40z"/><ellipse cx="0" cy="4" rx="12" ry="5" fill="#000" opacity="0.4"/>`)}
<!-- a pufferfish that puffs up now and then, tiny tetras, a hopping shrimp, a turning starfish, a snail -->
${cross(LOOPS.puffer, loopProgress(LOOPS.puffer, v.now), true, `<g class="inflate">${art(PUFFER_SVG, 10, 7, 6, true)}</g>`)}
${cross(LOOPS.tetras, loopProgress(LOOPS.tetras, v.now), true, range(7).map(i => `<g class="paddle" style="animation-delay:${f(-i * 0.4)}s"><g transform="translate(${i * 34 - 100} ${(i % 3) * 16 - 16})">${art(TETRA_SVG, 3, 3, 5)}</g></g>`).join(""))}
${cross(LOOPS.shrimp, loopProgress(LOOPS.shrimp, v.now), true, `<g class="hop2">${art(SHRIMP_SVG, 10, 6, 5)}</g>`)}
${pin(0.4, 0.93, `<g class="spin">${art(STARFISH_SVG, 7, 7, 6)}</g>`)}
${cross(LOOPS.snail, loopProgress(LOOPS.snail, v.now), true, art(SNAIL_SVG, 12, 7, 6))}
<!-- fish schools -->
${cross(LOOPS.yellow, loopProgress(LOOPS.yellow, v.now), true, school(3, false, false))}
${cross(LOOPS.blue, loopProgress(LOOPS.blue, v.now), true, school(2, true, true))}
<!-- visitors, each on its own timetable -->
${(Object.keys(VISITORS) as VisitorKind[]).map(k => visitor(k, v.now)).join("")}
<!-- the sea turtle strolls along the sand and turns around -->
${pin(SPOTS.turtle.x, SPOTS.turtle.y, `<g class="walk"><g class="face">${art(turtle(), 22, 9, 6)}</g></g>`)}
<!-- Molina on her rock -->
${pin(SPOTS.molina.x, SPOTS.molina.y, `<path class="rock" d="M-150 150C-135 85 -75 62 0 64S135 85 150 150z"/>
<g transform="translate(-112 -126) scale(7)">${molina(v.stage)}</g>`)}`
}

/** The whole backdrop. */
export const pond = (v: View, stage = v.stage, percent = v.percent) => `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%">
<style>${COLORS}${MOTION}</style>
<defs>
<linearGradient id="water" x1="0" y1="0" x2="0" y2="1"><stop offset="0" class="top"/><stop offset="1" class="bot"/></linearGradient>
<radialGradient id="sun" cx="0.3" cy="0" r="0.75"><stop offset="0" class="sun0"/><stop offset="1" class="sun1"/></radialGradient>
<linearGradient id="fog" x1="0" y1="0" x2="0" y2="1"><stop offset="0.45" class="fog0"/><stop offset="1" class="fog1"/></linearGradient>
<radialGradient id="vig" cx="0.5" cy="0.45" r="0.8"><stop offset="0.6" class="vig0"/><stop offset="1" class="vig1"/></radialGradient>
<linearGradient id="kelpA" x1="0" y1="1" x2="0" y2="0"><stop offset="0" class="ka0"/><stop offset="1" class="ka1"/></linearGradient>
<linearGradient id="kelpB" x1="0" y1="1" x2="0" y2="0"><stop offset="0" class="kb0"/><stop offset="1" class="kb1"/></linearGradient>
<linearGradient id="sand" x1="0" y1="0" x2="0" y2="1"><stop offset="0" class="sd0"/><stop offset="1" class="sd1"/></linearGradient>
</defs>
<svg width="100%" height="100%" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid slice">
<!-- water, surface shimmer and light rays -->
<rect width="${W}" height="${H}" fill="url(#water)"/>
<rect width="${W}" height="${H}" fill="url(#sun)"/>
<!-- far away: a hazy ridge and distant kelp, for depth -->
<path class="far" d="M0 ${H}V720C160 690 300 650 470 680S760 640 930 670S1250 630 1420 665S1560 650 ${W} 660V${H}z"/>
${[90, 410, 690, 1010, 1290].map((x, i) => `<path class="far" d="M${x} ${H}C${x - 12} 640 ${x + 20} 560 ${x + 8} ${470 + rnd(i, 30) * 90}C${x + 26} 560 ${x + 18} 660 ${x + 14} ${H}Z"/>`).join('')}
<rect width="${W}" height="${H}" fill="url(#fog)"/>
<path class="shine wave" d="${waves(26, 14)}"/>
${[250, 620, 980, 1330].map((x, i) => `<path class="ray" style="animation-delay:${-i * 2.3}s" d="M${x - 60} 0h120l${140 + i * 30} ${H}h-260z"/>`).join('')}
<!-- lily pads floating at the surface -->
${[[140, 70], [390, 46], [1180, 58], [1440, 80]].map(([x = 0, r = 0], i) => lily(x, r, i)).join('')}
<!-- plankton: more of it glows as the context fills -->
${motes(10 + stage * 12)}
<!-- kelp on both sides, away from the chat in the middle -->
${[30, 80, 130, 185, 240, 300].map((x, i) => kelp(x, 280 + rnd(i, 11) * 320, 30 - rnd(i, 12) * 60, i % 2 ? 'kelpA' : 'kelpB', i)).join('')}
${[1150, 1205, 1260, 1520, 1575].map((x, i) => kelp(x, 240 + rnd(i, 13) * 260, 30 - rnd(i, 14) * 60, i % 2 ? 'kelpB' : 'kelpA', i + 9)).join('')}
<!-- sandy floor with pebbles, moss and grass -->
<path class="sand2" d="M0 ${H}V810C300 780 600 830 900 805S1400 770 ${W} 800V${H}z"/>
<path class="sand" d="M0 ${H}V840C350 815 700 860 1000 835S1450 820 ${W} 840V${H}z"/>
${[[260, 70], [330, 55]].map(([x = 0, r = 0]) => `<ellipse class="moss" cx="${x}" cy="828" rx="${r}" ry="${r * 0.55}"/>`).join('')}
${range(9).map(i => `<ellipse class="peb" cx="${f(420 + rnd(i, 17) * 700)}" cy="${f(848 + rnd(i, 18) * 30)}" rx="${f(6 + rnd(i, 19) * 9)}" ry="${f(4 + rnd(i, 20) * 4)}"/>`).join('')}
${[40, 200, 360, 470, 1100, 1210, 1590].map((x, i) => tuft(x, 838, 40 + rnd(i, 21) * 50, i)).join('')}
<!-- two striped fish circling the orange anemone -->
<g transform="translate(760 808)">${[0, -5].map(d => `<g class="orbit" style="animation-delay:${d}s">${art(STRIPEY_SVG, 8, 5, 3)}</g>`).join('')}</g>
<!-- sunlight dancing on the sand -->
${[0, 1].map(g => `<g class="caus" style="animation-delay:${-g * 4.5}s">${range(5).map(i => `<ellipse cx="${f(150 + (i * 2 + g) * 140 + rnd(i, 31 + g) * 60)}" cy="${f(852 + rnd(i, 33 + g) * 18)}" rx="${f(30 + rnd(i, 35 + g) * 30)}" ry="5"/>`).join('')}</g>`).join('')}
<!-- sea anemones and more grass, kept low so the chat stays clear -->
${[[520, "anemA"], [760, "anemB"], [1060, "anemA"], [1360, "anemB"]].map(([x, c], i) => anemone(Number(x), String(c), i)).join("")}
${[600, 690, 870, 990, 1320, 1450].map((x, i) => tuft(x, 842, 30 + rnd(i, 22) * 35, i + 20)).join("")}
<!-- bubbles: more of them as the context fills -->
${range(6 + stage * 4).map(bubble).join('')}
<rect width="${W}" height="${H}" fill="url(#vig)"/>
</svg>
${creatures(v)}
<!-- context badge, pinned to the top-left -->
<svg width="100%" height="100%" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMinYMin meet">
<rect class="badge" x="40" y="40" width="170" height="90" rx="16" stroke-width="2.5"/>
<text class="pct" x="125" y="86" text-anchor="middle" font-family="sans-serif" font-weight="bold" font-size="36">${percent}%</text>
<text class="lbl" x="125" y="116" text-anchor="middle" font-family="sans-serif" font-size="19">context</text>
</svg>
</svg>`
